import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import SnackBar from "@/components/SnackBar.vue";
import EditProject from "@/components/TimeSheets/PopUps/EditProject.vue";
import DeleteProject from "@/components/TimeSheets/PopUps/DeleteProject.vue";
import { get_projects } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import CreateProject from "@/components/TimeSheets/PopUps/CreateProject.vue";
import { get_activities_list } from "@/mixins/GetTimeSheetActivitiesList.js";
export default {
  mixins: [get_activities_list],
  components: {
    DeleteProject,
    EditProject,
    SnackBar,
    CreateProject
  },
  data() {
    return {
      projectHeaders: [{
        title: "Name",
        value: "project_name",
        sortable: false
      }, {
        title: "Activities",
        value: "project_activities",
        sortable: false
      }, {
        title: "Type",
        value: "project_source",
        sortable: false
      }, {
        title: "Action",
        value: "actions",
        sortable: false
      }],
      fixed: true,
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      projectitems: {},
      projectDeletion: false,
      projectEdition: false,
      componentCheck: 0,
      loading: false,
      tableHeight: 0,
      height: 0,
      tableData: [],
      loadingBtn: false,
      selectedType: "ALL",
      CreatProjectDialog: false,
      activityData: [],
      searchQuery: "",
      currentPage: 1,
      itemsPerPage: 10
    };
  },
  async created() {
    this.tableHeight = window.innerHeight - 290;
    await this.fetch_projectes();
    await this.get_activities_list();
    let selectData = this.ActivityList;
    selectData.forEach(element => {
      this.activityData.push({
        title: element.activity_name,
        value: element.activity_name
      });
    });
  },
  computed: {
    filteredItems() {
      let filtered = this.tableData;
      if (this.selectedType !== "ALL") {
        filtered = filtered.filter(item => item.project_source === this.selectedType);
      }
      if (this.searchQuery && this.searchQuery.trim() !== "") {
        const searchTerm = this.searchQuery.toLowerCase().trim();
        filtered = filtered.filter(item => item.project_name && item.project_name.toLowerCase().includes(searchTerm) || item.project_activities && item.project_activities.some(activity => activity.toLowerCase().includes(searchTerm)) || item.project_source && item.project_source.toLowerCase().includes(searchTerm));
      }
      return filtered;
    },
    sortedAndPaginatedItems() {
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        const aValue = a.project_name ? a.project_name.toLowerCase() : "";
        const bValue = b.project_name ? b.project_name.toLowerCase() : "";
        return aValue.localeCompare(bValue);
      });
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.CommonVuetifyObj = useDisplay();
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage(newVal) {
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  methods: {
    edit_item(item) {
      this.projectitems = item;
      this.componentCheck = 1;
      this.projectEdition = true;
    },
    delete_item(item) {
      this.projectitems = item;
      this.componentCheck = 2;
      this.projectDeletion = true;
    },
    add_mutation() {
      this.CreatProjectDialog = true;
      this.componentCheck = 3;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.projectEdition = false;
      this.projectDeletion = false;
      this.CreatProjectDialog = false, this.fetch_projectes();
    },
    async fetch_projectes() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_projects, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.get_projects);
        this.tableData = [];
        this.loading = false;
        this.tableData = response.data;
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    handleSortChange() {}
  }
};
